head.script:
// 테스트 설명, 유효성 값 설정
//  - 본 샘플(_3)은 senseReader=true 시 동작(@spec)을 검증한다.
//  - description 은 _1(gridView_P_ignoreNonEditableCell_1.xml) 과 동일하게 유지.
scwin.tData = {
    "description" : "[gridView > P > ignoreNonEditableCell]<br/>키보드로 포커스 이동 시 편집 불가 상태(disabled, readonly)인 Body Cell 을 건너 뛸지 설정합니다.",
    "validation" : [
        "senseReader=true 이면 ignoreNonEditableCell 속성값에 관계없이 편집 불가 상태(disabled, readonly)인 Body Cell 을 건너 뛰어 포커스가 이동합니다.",
        "senseReader=true 이면 접근성 전용 추가 동작(radio, link, button 특수 처리 등)이 적용됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1(gdl_boolean)은 초기 selectedIndex 미적용 → 기본값 명시 설정 (코드값 미설정="1"/true="2"/false="3")
    //  기본 시나리오: senseReader=true(코드 "2") + ignoreNonEditableCell=false(코드 "3")
    //  → ignoreNonEditableCell 은 원래 건너뛰지 않는 값(false)인데도 senseReader=true 오버라이드로 건너뛰는지 입증.
    con_senseReader.setValue("2");
    con_ignoreNonEditableCell.setValue("3");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - con_senseReader           : 공통 gdl_boolean → getText() ('true' 면 값 무관 건너뜀 + 접근성 특수 처리)
//  - con_ignoreNonEditableCell : 공통 gdl_boolean → getText() ('' 미설정 / 'true' / 'false')
//  - senseReader/ignoreNonEditableCell 는 렌더 시 결정 → con 변경 후 "Target 재생성"(btn_createTarget) 으로만 반영
//  - focusMode="cell" 고정, focusMove 기본값(true) 유지 → 키보드 셀 포커스 이동 확인용
//  - Body 편집 불가/특수 inputType 셀 구성:
//      col1(text)=편집가능(시작) / col2(text)=readOnly / col3(text)=disabled
//      col4(button)=readOnly(접근성 특수 처리) / col5(link)=readOnly / col6(radio) / col7(text)=편집가능(끝)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vSenseReader = con_senseReader.getText();
    let vIgnore      = con_ignoreNonEditableCell.getText();

    // focusMode 는 키보드 포커스 이동 확인을 위해 cell 고정
    //  readOnlyBackgroundColor(회색) / disabledBackgroundColor(노랑) 로 편집 불가 셀을 시각 구분
    let properties = {
        focusMode : "cell",
        readOnlyBackgroundColor : "#D3D3D3",
        disabledBackgroundColor : "#FFF9C4"
    };

    // senseReader : 'true' 면 값 무관 편집 불가 셀 건너뜀 + 접근성 특수 처리
    if (vSenseReader === 'true') {
        properties.senseReader = true;
    } else if (vSenseReader === 'false') {
        properties.senseReader = false;
    }

    // ignoreNonEditableCell : '' 미설정 시 속성 제외(기본 false)
    if (vIgnore === 'true') {
        properties.ignoreNonEditableCell = true;
    } else if (vIgnore === 'false') {
        properties.ignoreNonEditableCell = false;
    }

    let cList = $c.gcm.createCList(properties);

    let lblDesc = '[전제] col2=readOnly(text), col3=disabled(text), col4=button(readOnly), col5=link(readOnly), col6=radio (편집 가능 셀: col1, col7)'
        + '\n[배경색] readOnly 셀=회색(#D3D3D3), disabled 셀=노랑(#FFF9C4) 로 편집 불가 셀 시각 구분'
        + '\n[현재] senseReader=' + (vSenseReader === '' ? '(미설정=기본 false)' : vSenseReader)
        + ', ignoreNonEditableCell=' + (vIgnore === '' ? '(미설정=기본 false)' : vIgnore)
        + '\n[절차] col1 셀 클릭 후 Tab 을 반복 입력'
        + '\n[확인] 하단 출력의 이동 셀 위치'
        + '\n  (검증1) senseReader=true 면 ignoreNonEditableCell 값과 무관하게 col2/col3(편집 불가 text) 를 건너뜀 -> 해당 셀은 oncellindexchange 미발생'
        + '\n  (검증2) senseReader=true 면 편집 불가라도 col4(button) 등에는 접근성 특수 처리가 적용되어 포커스가 정지(이동 셀 col=3 출력)';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // 포커스 이동 확인용 DataList 인라인 생성 (7컬럼 → 공통 헬퍼 4컬럼 한계로 인라인 사용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col6" name="col6" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col7" name="col7" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    scwin.fillData();

    // target 생성 (7컬럼 Body 그리드)
    await scwin.createGridView(cList);

    // 편집 불가 셀 설정 (편집 가능 셀 사이에 편집 불가/특수 inputType 셀 배치)
    target1.setColumnReadOnly(1, true);   // col2(text) readOnly
    target1.setColumnDisabled(2, true);   // col3(text) disabled
    target1.setColumnReadOnly(3, true);   // col4(button) readOnly → senseReader 접근성 특수 처리 대상
    target1.setColumnReadOnly(4, true);   // col5(link) readOnly → senseReader 접근성 특수 처리 대상

    // 첫번째 편집 가능 셀(col1)에 포커스
    target1.setFocusedCell(0, 0, true);
}



// 포커스 이동 확인용 데이터 (6행)
//  - col4(button) : 버튼 라벨 / col5(link) : 링크 텍스트 / col6(radio) : Y/N (trueValue=Y)
scwin.fillData = function () {
    let rows = [
        { col1: "A1", col2: "B1", col3: "C1", col4: "실행", col5: "상세보기", col6: "Y", col7: "G1" },
        { col1: "A2", col2: "B2", col3: "C2", col4: "실행", col5: "상세보기", col6: "N", col7: "G2" },
        { col1: "A3", col2: "B3", col3: "C3", col4: "실행", col5: "상세보기", col6: "Y", col7: "G3" },
        { col1: "A4", col2: "B4", col3: "C4", col4: "실행", col5: "상세보기", col6: "N", col7: "G4" },
        { col1: "A5", col2: "B5", col3: "C5", col4: "실행", col5: "상세보기", col6: "Y", col7: "G5" },
        { col1: "A6", col2: "B6", col3: "C6", col4: "실행", col5: "상세보기", col6: "N", col7: "G6" }
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성
//  - oncellindexchange : Tab/Enter/방향키 등으로 포커스 셀이 실제 이동할 때마다 발생
//    (senseReader=true 로 건너 뛴 편집 불가 셀에서는 발생하지 않음 → 출력 로그로 확인)
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:640px;height:260px;" ev:oncellindexchange="scwin.target1_oncellindexchange">';
    s += '<w2:caption style="" id="caption1" value="ignoreNonEditableCell (senseReader) 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="80" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="80" style="" inputType="text" id="column2" value="col2(RO)"></w2:column>';
    s += '<w2:column width="80" style="" inputType="text" id="column3" value="col3(DIS)"></w2:column>';
    s += '<w2:column width="90" style="" inputType="text" id="column4" value="col4(btn)"></w2:column>';
    s += '<w2:column width="90" style="" inputType="text" id="column5" value="col5(link)"></w2:column>';
    s += '<w2:column width="80" style="" inputType="text" id="column6" value="col6(radio)"></w2:column>';
    s += '<w2:column width="80" style="" inputType="text" id="column7" value="col7"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="80" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    s += '<w2:column width="80" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    s += '<w2:column width="80" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    s += '<w2:column width="90" style="" inputType="button" id="col4" dataList="col4"></w2:column>';
    s += '<w2:column width="90" style="" inputType="link" id="col5" dataList="col5"></w2:column>';
    s += '<w2:column width="80" style="" inputType="radio" id="col6" dataList="col6" trueValue="Y" falseValue="N" groupName="grp_rdo"></w2:column>';
    s += '<w2:column width="80" style="" inputType="text" id="col7" dataList="col7"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 셀 포커스가 실제 이동(변경)될 때 호출 (oncellindexchange)
//  - Tab 입력으로 포커스 셀이 바뀔 때마다 이동 셀과 이전 셀 위치를 하단에 누적 출력
//  - senseReader=true 로 건너 뛴 편집 불가 셀(col2/col3)에서는 이 이벤트가 발생하지 않으므로,
//    출력된 이동 셀 시퀀스로 어느 셀을 건너 뛰었는지, 어느 편집 불가 셀(col4 button)에 특수 처리로 정지했는지 확인
scwin.target1_oncellindexchange = function (rowIndex, columnIndex, oldRow, oldColumnIndex) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("oncellindexchange 발생 → 이동 셀 (row: " + rowIndex + ", col: " + columnIndex
        + "), 이전 셀 (row: " + oldRow + ", col: " + oldColumnIndex + ")");
}
